<?php
session_start();require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/admin_layout.php';require_admin_user('articles.manage');
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf_token($_POST['csrf_token']??null);try{if(isset($_POST['delete_id'])){$pdo->prepare('DELETE FROM tag_aliases WHERE id=?')->execute([(int)$_POST['delete_id']]);$message='Alias წაიშალა.';}else{$tagId=(int)($_POST['tag_id']??0);$alias=trim((string)($_POST['alias']??''));if(!$tagId||$alias==='')throw new RuntimeException('თეგი და alias აუცილებელია.');$pdo->prepare('INSERT INTO tag_aliases(tag_id,alias) VALUES(?,?) ON DUPLICATE KEY UPDATE tag_id=VALUES(tag_id)')->execute([$tagId,$alias]);$message='Alias შენახულია.';}}catch(Throwable $e){$error=$e->getMessage();}}
$tags=$pdo->query('SELECT id,name FROM tags ORDER BY name')->fetchAll();$aliases=$pdo->query('SELECT ta.id,ta.alias,t.name canonical FROM tag_aliases ta JOIN tags t ON t.id=ta.tag_id ORDER BY t.name,ta.alias')->fetchAll();admin_page_start('Club / Tag aliases');admin_alert($message);admin_alert($error,'error');?>
<section class="admin-card admin-card--narrow"><div class="admin-card__header"><h2>ახალი alias</h2></div><form method="post" class="admin-form"><?php admin_csrf_field(); ?><label>ძირითადი თეგი<select name="tag_id" required><?php foreach($tags as $tag): ?><option value="<?= (int)$tag['id'] ?>"><?= htmlspecialchars($tag['name']) ?></option><?php endforeach; ?></select></label><label>ქართული/ალტერნატიული სახელი<input name="alias" required></label><button class="admin-button admin-button--primary">შენახვა</button></form></section>
<section class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Canonical</th><th>Alias</th><th></th></tr></thead><tbody><?php foreach($aliases as $row): ?><tr><td><?= htmlspecialchars($row['canonical']) ?></td><td><?= htmlspecialchars($row['alias']) ?></td><td><form method="post"><?php admin_csrf_field(); ?><button name="delete_id" value="<?= (int)$row['id'] ?>" class="admin-button--danger">წაშლა</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php admin_page_end(); ?>
